{"hypotheses": [
  {
    "name": "Profitability-Momentum Quality Overlay",
    "mechanism": "Combining long positions in OperProf and Mom12m with a short in Beta, this composite exploits that high-profitability stocks with strong momentum and low market beta reflect persistently improving fundamentals and capital discipline. Beta's inclusion hedges market exposure, capturing a unique risk/behavioral anomaly not targeted by any primitive alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OperProf"},
        {"weight": 1.0, "primitive": "Mom12m"},
        {"weight": -1.0, "primitive": "Beta"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "Beta", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "large", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 1.1,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Analyst Disagreement Defensive Alpha",
    "mechanism": "By going long ForecastDispersion and AnalystRevision, while shorting RealizedVol, the composite targets idiosyncratic alpha when analysts disagree but revisions improve, and overall price volatility is low. The interaction suggests greater investor uncertainty resolved positively, distinct from individual effects.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": 1.0, "primitive": "AnalystRevision"},
        {"weight": -1.0, "primitive": "RealizedVol"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "correlation", "primitive": "AnalystRevision", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Leverage-Momentum Macro Hedge",
    "mechanism": "Long Mom6m and short Leverage combined with long TERM_SPREAD_POSITIVE regime exploits that momentum premiums are stronger for less-levered firms when the yield curve is upward sloping. This synergy offers macro-sensitive exposure, as leverage risk is less penalized in healthy environments.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Mom6m"},
        {"weight": -1.0, "primitive": "Leverage"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 1.0,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Intangible Value and Conservative Investment",
    "mechanism": "By combining long IntanBM with short AssetGrowth and long CF, this composite captures undervalued intangible-rich firms that restrain asset growth and generate high cash flow — a blend reflective of efficient capital allocation and hidden value not fully incorporated into prices.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "IntanBM"},
        {"weight": -1.0, "primitive": "AssetGrowth"},
        {"weight": 1.0, "primitive": "CF"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "AssetGrowth", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Seasonal Earnings Surprise Enhancer",
    "mechanism": "Going long EarningsSurprise and MomSeason, and shorting Illiquidity, this composite isolates stocks with recent positive surprises and persistent seasonal momentum, avoiding illiquid names to reduce noise. This targets repeatable post-earnings drift strengthened by seasonal flows.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "EarningsSurprise"},
        {"weight": 1.0, "primitive": "MomSeason"},
        {"weight": -1.0, "primitive": "Illiquidity"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "MomSeason", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 1.2,
    "expected_decay_half_life_months": 15
  },
  {
    "name": "Shareholder Return Discipline",
    "mechanism": "Long NetPayoutYield and ShareRepurchase, short CompEquIss, this composite favors firms returning capital through dividends and buybacks, while avoiding those funding via equity issuance. The combination captures shareholder-friendly cultures overlooked by single measures.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "NetPayoutYield"},
        {"weight": 1.0, "primitive": "ShareRepurchase"},
        {"weight": -1.0, "primitive": "CompEquIss"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 48
  },
  {
    "name": "Organizational and Brand Capital Advantage",
    "mechanism": "Combining long OrgCap and BrandInvest, shorting DebtIssuance, this composite targets firms with strong organizational and brand assets that avoid diluting value via new debt. Such intangible investments combined with conservative financing signal sustainable competitive advantage.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": 1.0, "primitive": "BrandInvest"},
        {"weight": -1.0, "primitive": "DebtIssuance"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "correlation", "primitive": "OrgCap", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "large", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Customer Demand and Supply Chain Quality Premium",
    "mechanism": "By going long CustomerMomentum and iomom_supp, and shorting Inventory Growth, the composite targets firms with rising end-market demand and robust suppliers, while avoiding those with accumulating inventories, capturing superior supply chain dynamics driving returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "CustomerMomentum"},
        {"weight": 1.0, "primitive": "iomom_supp"},
        {"weight": -1.0, "primitive": "InvGrowth"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "correlation", "primitive": "CustomerMomentum", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 1.05,
    "expected_decay_half_life_months": 20
  }
]}
